// th18_s5_w08 - TH18 v1.00a Stage 5 midstage MainSub07 (st05.ecl.txt:1178-1190).
// Closure: GirlC01 (518-539) -> async GirlC01_at (541-582).
// Source t0 (MainSub07 entry, first enmCreate pair) = card frame 120; the 120-frame
// practice buffer precedes it.  The wave schedule is 18 pairs at 60-frame spacing.

const TIME_LIMIT: int = 2000;          // 120 buffer + 1880 local window (see meta.toml)
const TH18_RICE: int = 480;            // type8, base radius 2.4, colors 0..15

// GirlC01 518-539.  setHurtbox(32,32)/setHitbox(24,24) -> native radii 16/12.
// Training pool: zako kept invulnerable, source hurtbox/hitbox retained.
// enmCreateM (520 mirror variant) flips movement angles; firing angles are not mirrored.
async sub girl_main(mirror: int) {
    set_hurtbox(16fx);                 // S:526
    set_hitbox(12fx);                  // S:527
    set_invuln(65535);
    spawn girl_shot();                 // S:528 async GirlC01_at

    // S:529 moveVel((pi+10deg)+RANDF2*10deg, 2.0)
    var u1: fx = ((rand(65536)-32768) as fx)/32768;      // source %RANDF2
    var off1: int = (u1 * 1820fx) as int;                // 0.17453292 rad = 1820 BAM
    var a1: angle = 190deg + (off1 as angle);
    if mirror != 0 { a1 = 180deg - a1; }
    move_vel(0, a1, 2.0fx, EASE_LINEAR);                 // immediate speed/angle write
    // S:530 moveVelTime(200, 1, pi+RANDF2*10deg, 0.5): mode1 = t^2 on angle and speed.
    var u2: fx = ((rand(65536)-32768) as fx)/32768;
    var off2: int = (u2 * 1820fx) as int;
    var a2: angle = 180deg + (off2 as angle);
    if mirror != 0 { a2 = 180deg - a2; }
    move_vel(200, a2, 0.5fx, EASE_QUAD_IN);
    wait(200);                         // S:531
    // S:532 moveVelTime(200, 1, pi+RANDF2*10deg, -1.0), independent sample at t=200.
    var u3: fx = ((rand(65536)-32768) as fx)/32768;
    var off3: int = (u3 * 1820fx) as int;
    var a3: angle = 180deg + (off3 as angle);
    if mirror != 0 { a3 = 180deg - a3; }
    move_vel(200, a3, -1.0fx, EASE_QUAD_IN);
    loop { wait(1000); }               // S:533-537 tail loop
}

// GirlC01_at 541-582.
// etAim(3) fixed-direction ring: alpha + 2*pi*i/5, one layer; etSpeed(2.0,1.5) with
// M=1 uses 2.0; etCount(5,1); etDist(32) pushes each bullet 32px along its own angle.
// Source samples ANGLE_PLAYER once (553) and reuses it for all 66 outer rounds.
// Inner $D (3/10/14/16) shots every 8 frames, then rank wait 80/40/30/24.
async sub girl_shot() {
    wait(60);                          // S:544
    var base: angle = aim_player();    // S:553, once
    sh_reset(0);
    sh_sprite(0, TH18_RICE, 4);        // S:547 type8 color4
    sh_ring(0, 1);                     // S:546 mode3
    sh_aim(0, 0);
    sh_count(0, 5, 1);                 // S:548
    sh_speed(0, 2.0fx, 0fx);           // S:550, single layer -> 2.0
    sh_angle(0, base, 0deg);           // S:549
    sh_dist(0, 32fx);                  // S:552

    var rank: int = global(GVAR_RANK);
    var n: int = 3;
    var gap: int = 80;
    if rank == RANK_NORMAL { n = 10; gap = 40; }
    if rank == RANK_HARD   { n = 14; gap = 30; }
    if rank == RANK_LUNATIC{ n = 16; gap = 24; }
    for c in 0..66 {                   // S:555 $C=66
        for i in 0..n {                // S:560 outer $D value
            sh_fire(0);                // S:564-565 etAngle(%A,0)/etOn
            wait(8);                   // S:566
        }
        wait(gap);                     // S:569-578
    }
}

// Practice shell: control enemy at (0,0), body collision off, hosts the segment timer.
async sub shell_main() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, none, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

// MainSub07 1178-1190 plus the 120-frame local-wave buffer.
sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, shell_main);
    wait(120);                         // practice buffer before MainSub07 t0
    for i in 0..18 {                   // S:1181 $A=18 pairs
        // Two independent %RANDF draws for normal and mirror y (1184/1185).
        var r1: fx = ((rand(65536)-32768) as fx)/65536 + 0.5fx;   // source %RANDF [0,1)
        var y1: fx = 96fx + r1*96fx;
        _ = spawn_enemy(192fx, y1, 600, 0, 0, 0, girl_main(0));   // S:1184 enmCreate
        var r2: fx = ((rand(65536)-32768) as fx)/65536 + 0.5fx;
        var y2: fx = 96fx + r2*96fx;
        _ = spawn_enemy(-192fx, y2, 600, 0, 0, 0, girl_main(1));  // S:1185 enmCreateM
        wait(60);                      // S:1186
    }
    loop { wait(1000); }
}
